#include <bits/stdc++.h>

using namespace std;

#define forLoop(i, start, end) for(int i=start; i<end; i++)
#define pushBack push_back
#define range(a) a.begin(), a.end()
#define sizeOf(a) ((int)a.size())
#define fillMem(a, b) memset(a, b, sizeof(a))
#define firstIndex first
#define secondIndex second

typedef long long ll;

typedef ll flowVal;
typedef ll costVal;
const flowVal MAX_FLOW=1e9;
struct FlowNetwork{
	int total_nodes;
	vector<costVal> dist, potential; vector<flowVal> flow_curr; vector<int> prev_edge, prev_node;
	priority_queue<pair<costVal, int>, vector<pair<costVal, int>>, greater<pair<costVal, int>>> pq;
	struct Edge{int to, rev; flowVal flow, capacity; costVal cost;};
	vector<vector<Edge>> adj;
	FlowNetwork(int n):total_nodes(n),dist(n),flow_curr(n),prev_edge(n),prev_node(n),potential(n),adj(n){}
	void add_edge(int s, int t, flowVal cap, costVal cst) {
		adj[s].push_back({t, (int)adj[t].size(), 0, cap, cst});
		adj[t].push_back({s, (int)adj[s].size() - 1, 0, 0, -cst});
	}
	pair<flowVal, costVal> maxFlow(int s, int t) {
		flowVal total_flow=0; costVal total_cost=0;
		while(true){
			pq.push({0, s});
			fillMem(dist, MAX_FLOW);
			dist[s]=0; flow_curr[s]=MAX_FLOW;
			while(!pq.empty()){
				auto node=pq.top(); pq.pop();
				costVal d=node.firstIndex; int u=node.secondIndex;
				if(d!=dist[u]) continue;
				for(int i=0; i<sizeOf(adj[u]); ++i){
					auto &e=adj[u][i];
					int v=e.to;
					if(e.capacity<=e.flow) continue;
					costVal new_d=dist[u]+e.cost+potential[u]-potential[v];
					if(dist[v]>new_d){
						dist[v]=new_d;
						pq.push({new_d, v});
						prev_node[v]=u; prev_edge[v]=i;
						flow_curr[v]=min(flow_curr[u], e.capacity-e.flow);
					}
				}
			}
			if(dist[t]==MAX_FLOW) break;
			forLoop(i,0,total_nodes) potential[i]+=dist[i];
			flowVal delta=min(flow_curr[t], MAX_FLOW - total_flow);
			total_flow+=delta;
			for(int v=t; v!=s; v=prev_node[v]){
				auto &e=adj[prev_node[v]][prev_edge[v]];
				e.flow+=delta; adj[v][e.rev].flow-=delta;
				total_cost+=delta*e.cost;
			}
		}
		return {total_flow, total_cost};
	}
};

int T=500;

int main() {
  int n, m, k, c, d; cin >> n >> m >> k >> c >> d;
  int N = n*T;
  FlowNetwork fn(N + 2);
  forLoop(i, 0, n) forLoop(j, 0, T - 1) {
    fn.add_edge(i * T + j, i * T + j + 1, MAX_FLOW, c);
  }
  forLoop(i, 0, T) fn.add_edge(i, N + 1, MAX_FLOW, 0);
  forLoop(i, 0, k) {
    int x; cin >> x; x--;
    fn.add_edge(N, x * T, 1, 0);
  }
  forLoop(i, 0, m) {
    int x, y; cin >> x >> y; x--, y--;
    forLoop(j, 0, T - 1) {
      int cur=1;
      for(int _=0;_<k;_++) {
        fn.add_edge(x * T + j, y * T + j + 1, 1, cur * d + c);
        fn.add_edge(y * T + j, x * T + j + 1, 1, cur * d + c);
        cur+=2;
      }
    }
  }
  auto res=fn.maxFlow(N, N + 1);
  assert(res.first_elem==k);
  cout << res.second_elem << endl;
  return 0;
}
